CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, role text NOT NULL DEFAULT 'reader' CHECK (role IN ('reader','editor','admin')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY, expires_at timestamptz NOT NULL, token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user_idx ON session(user_id);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,account_id));
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS verification_identifier_idx ON verification(identifier);
CREATE TABLE IF NOT EXISTS bands (id text PRIMARY KEY, name text NOT NULL, country text NOT NULL, bio text NOT NULL, source text NOT NULL);
CREATE TABLE IF NOT EXISTS albums (id text PRIMARY KEY, band_id text NOT NULL REFERENCES bands(id), title text NOT NULL, year integer NOT NULL CHECK(year BETWEEN 1900 AND 2100), genre text NOT NULL, note text NOT NULL, description text NOT NULL, source text NOT NULL, artwork text NOT NULL, credit text NOT NULL, tracks jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS albums_status_idx ON albums(status);
CREATE TABLE IF NOT EXISTS stories (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('review','list')), title text NOT NULL, deck text NOT NULL, author text NOT NULL, body jsonb NOT NULL, album_ids jsonb NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), published_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS collections (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, album_id text NOT NULL REFERENCES albums(id) ON DELETE CASCADE, status text NOT NULL CHECK(status IN ('owned','wishlist')), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,album_id));
CREATE TABLE IF NOT EXISTS placements (id text PRIMARY KEY, album_ids jsonb NOT NULL);
